import{c as o,Q as l,j as a,m as r}from"./chunks/framework.rWdQudnF.js";const g=JSON.parse('{"title":"C2与闭环控制风格","description":"","frontmatter":{"title":"C2与闭环控制风格"},"headers":[],"relativePath":"综合知识/架构设计/架构风格与模式/常用架构风格/C2与闭环控制风格.md","filePath":"综合知识/架构设计/架构风格与模式/常用架构风格/C2与闭环控制风格.md","lastUpdated":null}'),e={name:"综合知识/架构设计/架构风格与模式/常用架构风格/C2与闭环控制风格.md"};function i(n,t,s,u,c,_){return l(),a("div",null,[...t[0]||(t[0]=[r('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] C2 风格：通过连接件绑定并行构件网络</li><li>[ ] 闭环控制（过程控制）：反馈循环</li><li>[ ] C2 风格四组织规则</li><li>[ ] 闭环典型场景（恒温/巡航/机器人运动）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="c2-体系结构风格" tabindex="-1">C2 体系结构风格 <a class="header-anchor" href="#c2-体系结构风格" aria-label="Permalink to &quot;C2 体系结构风格&quot;">​</a></h3><blockquote><p>🎯 C2 风格概括：<strong>通过连接件绑定在一起的按照一组规则运作的并行构件网络</strong>。</p></blockquote><p><strong>四组织规则：</strong></p><ol><li>构件和连接件都有<strong>顶部</strong>和<strong>底部</strong></li><li>构件顶部 → 连接件底部，构件底部 → 连接件顶部，<strong>构件间不允许直接连接</strong></li><li>一个连接件可以和任意数目的构件和连接件连接</li><li>两个连接件直接连接时，必须<strong>底部到顶部</strong></li></ol><blockquote><p>⚠️ 构件与构件的关系：<strong>通过连接件间接连接</strong>（不是直接连接）</p></blockquote><h3 id="闭环控制-过程控制-风格" tabindex="-1">闭环控制（过程控制）风格 <a class="header-anchor" href="#闭环控制-过程控制-风格" aria-label="Permalink to &quot;闭环控制（过程控制）风格&quot;">​</a></h3><ul><li>软件与硬件之间表示为<strong>反馈循环</strong></li><li>接受输入 → 确定输出 → 环境达到新状态</li><li>适合<strong>嵌入式系统</strong>，涉及连续动作与状态</li></ul><p><strong>典型场景（选择题高频）：</strong></p><ul><li>空调恒温控制（测量温度 → 比较期望值 → 调节开关）</li><li>轿车巡航定速（测速 → 比较期望速度 → 控制油门/刹车）</li><li>机器人运动控制</li></ul><blockquote><p>⚠️ 考题套路：看到&quot;恒温&quot;、&quot;定速巡航&quot;、&quot;持续测量-比较-调节&quot; → <strong>闭环/过程控制</strong></p></blockquote>',13)])])}const h=o(e,[["render",i]]);export{g as __pageData,h as default};
